topics.code:
#include <iostream>

int main() {
    int age = 17;
    std::cout << "next year: " << age + 1 << "\n";
    return 0;
}

#include <iostream>
#include <string>

int main() {
    std::string name = "Aman Sharma";
    std::cout << name << ", welcome\n";
    return 0;
}

#include <iomanip>
#include <iostream>

int main() {
    double marks = 87.456;
    std::cout << std::fixed << std::setprecision(1) << marks << "\n";
    return 0;
}

#include <iostream>

int main() {
    std::cout << "name\tmarks\n";
    std::cout << "Aman\t92\n";
    std::cout << "quote: \"done\"\n";
    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream input("Aman Sharma 92");
    std::string first, last;
    int marks = 0;
    input >> first >> last >> marks;
    std::cout << last << ", " << first << ": " << marks << "\n";
    return 0;
}

#include <iostream>
#include <sstream>

int main() {
    std::istringstream input("10   20");
    int a = 0, b = 0;
    input >> a >> b;
    std::cout << a + b << "\n";
    return 0;
}

#include <iostream>

int main() {
    std::cout << "a" << "b" << "c\n";
    return 0;
}

#include <iomanip>
#include <iostream>

int main() {
    std::cout << std::setfill('*') << std::setw(4) << 7 << "\n";
    return 0;
}

#include <iostream>

int main() {
    char nl = '\n';
    std::cout << static_cast<int>(nl) << "\n";
    return 0;
}

#include <iostream>
#include <sstream>
#include <string>

int main() {
    std::istringstream input("C++ is fun");
    std::string line;
    std::getline(input, line);
    std::cout << line << "\n";
    return 0;
}

