tasks.solution:
#include <iostream>

int gcd(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    std::cout << gcd(12, 18) << "\n";
    return 0;
}

#include <iostream>

int main() {
    int n = 4729;
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    std::cout << sum << "\n";
    return 0;
}

#include <iostream>

int main() {
    long long f = 1;
    for (int i = 2; i <= 6; ++i) f *= i;
    std::cout << f << "\n";
    return 0;
}

