#include <iostream>

int gcd(int a, int b) {
    while (b != 0) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main() {
    std::cout << gcd(12, 18) << "\n";
    return 0;
}

#include <iomanip>
#include <iostream>

double area(double r) { return 3.14159 * r * r; }
double area(double w, double h) { return w * h; }

int main() {
    std::cout << std::fixed << std::setprecision(2) << area(2.0) << "\n";
    std::cout << static_cast<int>(area(3.0, 4.0)) << "\n";
    return 0;
}

#include <iostream>

bool isPrime(int n) {
    for (int d = 2; d * d <= n; ++d) if (n % d == 0) return false;
    return n > 1;
}

int main() {
    std::cout << (isPrime(29) ? "prime" : "composite") << "\n";
    return 0;
}

#include <iostream>

long long power(int base, int exp) {
    return exp == 0 ? 1 : base * power(base, exp - 1);
}

int main() {
    std::cout << power(2, 10) << "\n";
    return 0;
}

#include <iostream>

long long fact(int n) { return n <= 1 ? 1 : n * fact(n - 1); }

int main() {
    std::cout << fact(5) << "\n";
    return 0;
}

