#include <iostream>

int main() {
    int a[] = {4, 5, 6};
    int* p = a;
    int sum = 0;
    for (int i = 0; i < 3; ++i) sum += *(p + i);
    std::cout << sum << "\n";
    return 0;
}

#include <iostream>

int main() {
    int data[5] = {1, 2, 3, 4, 5};
    for (int i = 0, j = 4; i < j; ++i, --j) {
        int t = data[i];
        data[i] = data[j];
        data[j] = t;
    }
    for (int v : data) std::cout << v << " ";
    std::cout << "\n";
    return 0;
}

#include <iostream>

int main() {
    int data[3] = {2, 4, 6};
    int* p = data;
    int* end = data + 3;
    int sum = 0;
    while (p != end) {
        sum += *p;
        ++p;
    }
    std::cout << sum << "\n";
    return 0;
}

#include <iostream>

void swap(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}

int main() {
    int x = 1, y = 2;
    swap(&x, &y);
    std::cout << x << " " << y << "\n";
    return 0;
}

#include <iostream>

int main() {
    int data[3] = {4, 9, 1};
    int* p = data;
    int best = *p;
    while (p != data + 3) {
        if (*p > best) best = *p;
        ++p;
    }
    std::cout << best << "\n";
    return 0;
}

#include <iostream>

void bump(int& value) { ++value; }

int main() {
    int score = 5;
    bump(score);
    std::cout << score << "\n";
    return 0;
}

