    return 0;
}

#include <iostream>
#include <memory>

int main() {
    auto data = std::make_unique<int[]>(4);
    for (int i = 0; i < 4; ++i) data[i] = i + 1;
    int sum = 0;
    for (int i = 0; i < 4; ++i) sum += data[i];
    std::cout << sum << "\n";
    return 0;
}

