    auto first = std::make_shared<int>(1);
    auto second = first;
    std::cout << first.use_count() << "\n";
    return 0;
}

#include <iostream>
#include <memory>
#include <vector>

int main() {
    std::vector<std::unique_ptr<int>> values;
    values.push_back(std::make_unique<int>(1));
    values.push_back(std::make_unique<int>(2));
    int sum = 0;
    for (const auto& v : values) sum += *v;
    std::cout << sum << "\n";
    return 0;
}

